using System;using System.Linq;using System.Reflection;using System.Threading.Tasks;using UnityEngine;using UnityEngine.AI;using Codice.Bosses;using Codice.Characters;using Codice.Mechanics;using Codice.Presentation;
public static class VerifyContentLab {
 static void Check(bool value,string message){if(!value)throw new Exception(message);}
 public static async Task<string> Run(){var room=UnityEngine.Object.FindAnyObjectByType<CombatTestRoom>();var p=RunDirector.Instance.Player;Check(room&&p,"Test room not initialized");room.pauseEnemies=false;p.SetNarrativeControlsBlocked(false);var flags=BindingFlags.Instance|BindingFlags.NonPublic;int count=0;foreach(var prefab in room.enemyPrefabs.Where(x=>x&&x.GetComponent<BossCharacter>())){room.ClearEnemies();await Task.Delay(100);var b=UnityEngine.Object.Instantiate(prefab).GetComponent<BossCharacter>();b.Initialize(p,1);b.enabled=false;var agent=b.GetComponent<NavMeshAgent>();Check(NavMesh.SamplePosition(p.transform.position+p.transform.forward*10,out var pos,8,NavMesh.AllAreas),"No navmesh");agent.Warp(pos.position);await Task.Delay(150);Check(b.GetComponent<ActorPresentation>().Body,"Missing animator "+prefab.name);var tick=typeof(BossCharacter).GetMethod(b.kind==BossKind.AngelKnight?"TickAngel":b.IsWarden?"TickWarden":"Update",flags);if(b.kind==BossKind.AngelKnight||b.IsWarden){typeof(BossCharacter).GetField("attackTimer",flags).SetValue(b,0f);tick.Invoke(b,new object[]{.02f});Check(b.State==BossState.Windup,"No windup "+prefab.name);string state=b.GetComponent<ActorPresentation>().CurrentState;Check(b.GetComponent<ActorPresentation>().Body.HasState(0,Animator.StringToHash(state)),"Missing action "+state);var resolve=typeof(BossCharacter).GetMethod(b.kind==BossKind.AngelKnight?"ResolveAngelAttack":"ResolveWardenAttack",flags);resolve.Invoke(b,null);if(b.CurrentAttack==BossAttack.Bow)Check(UnityEngine.Object.FindObjectsByType<AngelBolt>(FindObjectsSortMode.None).Length>0,"Missing projectile "+prefab.name);b.ApplyStun(.3f);float hp=p.State.Health;tick.Invoke(b,new object[]{.02f});Check(b.State==BossState.Recovery&&p.State.Health==hp,"Stun failed "+prefab.name);}b.ReceiveDamage(new DamageInfo{amount=999999,source=p.gameObject});await Task.Delay(100);Check(!b,"Boss death failed");count++;Debug.Log("[ContentLabTest] PASS "+prefab.name+" animator, telegraph, stun cancellation, death");}room.selected=0;Check(room.SpawnSelected(),"Lab spawn failed");Check(room.SpawnSelected(),"Second lab spawn failed");room.ClearEnemies();var bench=UnityEngine.Object.FindAnyObjectByType<ProceduralContentWorkbench>();bench.GeneratePreview();Check(bench.previewRoot.childCount>0,"Empty prop preview");return "PASS "+count+" boss prefabs in laboratory";}
}
